(() => {
'use strict';
const canvas=document.getElementById('arena'),ctx=canvas.getContext('2d');
const $=id=>document.getElementById(id);
const cards=[
 {id:'knight',name:'Knight',icon:'🛡️',cost:3,color:'#4b91bd',hp:190,damage:25,range:.065,speed:.105,rate:.82,kind:'melee'},
 {id:'archer',name:'Archer',icon:'🏹',cost:3,color:'#52ae83',hp:95,damage:18,range:.19,speed:.085,rate:1.05,kind:'range'},
 {id:'giant',name:'Giant',icon:'🗿',cost:5,color:'#c58b54',hp:430,damage:46,range:.075,speed:.048,rate:1.35,kind:'tank'},
 {id:'mage',name:'Spark mage',icon:'⚡',cost:4,color:'#9a70cb',hp:120,damage:32,range:.17,speed:.075,rate:1.2,kind:'splash'},
 {id:'scout',name:'Twin scouts',icon:'🥷',cost:2,color:'#df795f',hp:76,damage:15,range:.065,speed:.13,rate:.66,kind:'melee',count:2}
];
let dpr=1,w=0,h=0,aspect=1,last=0,playing=false,ended=false,elapsed=0,energy=5,chosen=null,hand=[],deckPos=0,units=[],shots=[],particles=[],towers=[],playerCrowns=0,enemyCrowns=0,aiWait=2.1,hintTimer=0,soundOn=false,audio;
const towerDefs=[{side:'enemy',x:.26,y:.19,type:'side'},{side:'enemy',x:.74,y:.19,type:'side'},{side:'enemy',x:.5,y:.105,type:'king'},{side:'player',x:.26,y:.81,type:'side'},{side:'player',x:.74,y:.81,type:'side'},{side:'player',x:.5,y:.895,type:'king'}];
function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);w=r.width;h=r.height;aspect=w/h;canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}
new ResizeObserver(resize).observe(canvas);resize();
function makeTower(d){return {...d,hp:d.type==='king'?600:390,max:d.type==='king'?600:390,range:d.type==='king'?.20:.18,damage:d.type==='king'?20:17,rate:d.type==='king'?.95:1.05,cool:Math.random()*.6,dead:false}}
function init(){playing=true;ended=false;elapsed=0;energy=5;chosen=null;units=[];shots=[];particles=[];playerCrowns=0;enemyCrowns=0;aiWait=2.1;towers=towerDefs.map(makeTower);deckPos=0;hand=[cards[0],cards[1],cards[2],cards[3]];renderHand();$('intro').classList.add('hidden');$('result').classList.add('hidden');updateHud();say('Select a card, then deploy on your side.',2200);last=performance.now()}
$('play').addEventListener('click',init);$('again').addEventListener('click',init);
function renderHand(){const el=$('hand');el.innerHTML='';hand.forEach((card,i)=>{const b=document.createElement('button');b.className='card'+(chosen===i?' selected':'')+(energy<card.cost?' disabled':'');b.style.setProperty('--c',card.color);b.innerHTML=`<span class="card-cost">${card.cost}</span><div class="card-art">${card.icon}</div><div class="card-name">${card.name}</div>`;b.setAttribute('aria-label',`${card.name}, costs ${card.cost} energy`);b.addEventListener('click',()=>selectCard(i));el.appendChild(b)})}
function selectCard(i){if(!playing)return;const c=hand[i];if(energy<c.cost){say('Not enough energy yet!',1000);beep(170,.08);return}chosen=chosen===i?null:i;renderHand();if(chosen!==null)say(`Place ${c.name} anywhere in your half.`,1500);else say('',0)}
function say(text,ms=1200){const el=$('hint');el.textContent=text;el.classList.toggle('show',!!text);hintTimer=ms}
function updateHud(){ $('player-score').textContent=playerCrowns;$('enemy-score').textContent=enemyCrowns;$('energy-count').textContent=`${energy.toFixed(1).replace('.0','')}/10`;const p=$('pips');if(p.children.length!==10)p.innerHTML=Array.from({length:10},()=>'<i class="pip"></i>').join('');[...p.children].forEach((x,i)=>x.classList.toggle('full',energy>=i+1));renderHand() }
function beep(freq=450,dur=.07){if(!soundOn)return;try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.frequency.value=freq;o.type='sine';g.gain.setValueAtTime(.055,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+dur);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+dur)}catch{}}
$('sound').addEventListener('click',()=>{soundOn=!soundOn;$('sound').textContent=soundOn?'♫':'♩';if(soundOn)beep()});
function pos(evt){const r=canvas.getBoundingClientRect();return{x:(evt.clientX-r.left)/r.width,y:(evt.clientY-r.top)/r.height}}
canvas.addEventListener('pointerdown',e=>{if(!playing||chosen===null)return;const p=pos(e);if(p.y<.53){say('Deploy troops on the lower, green side!',1100);return}if(p.y>.96)return;const card=hand[chosen];if(energy<card.cost){say('Not enough energy!',900);return}spawn(card,'player',Math.max(.09,Math.min(.91,p.x)),Math.max(.56,Math.min(.91,p.y)));energy-=card.cost;hand[chosen]=cards[(++deckPos+3)%cards.length];chosen=null;beep(560,.12);updateHud()});
function spawn(card,side,x,y){const n=card.count||1;for(let i=0;i<n;i++){units.push({side,card,x:x+(i-(n-1)/2)*.025,y:y+(i?-.018:0),hp:card.hp,max:card.hp,damage:card.damage,range:card.range,speed:card.speed,rate:card.rate,cool:Math.random()*.3,kind:card.kind,icon:card.icon,dead:false,hit:0})}}
function dist(a,b){return Math.hypot((a.x-b.x)*aspect,a.y-b.y)}
function enemyOf(side){return side==='player'?'enemy':'player'}
function targetTower(unit){const foes=towers.filter(t=>t.side===enemyOf(unit.side)&&!t.dead);if(!foes.length)return null;const sides=foes.filter(t=>t.type==='side');const pool=sides.length?sides:foes;return pool.reduce((a,b)=>dist(unit,a)<dist(unit,b)?a:b)}
function killTower(t){if(t.dead)return;t.dead=true;burst(t.x,t.y,'#ffdc81',18);if(t.type==='side'){if(t.side==='enemy')playerCrowns++;else enemyCrowns++;updateHud();if(playerCrowns>=3||enemyCrowns>=3)finish(playerCrowns>enemyCrowns)}else finish(t.side==='enemy');beep(t.type==='king'?120:245,.32)}
function hurt(target,n){target.hp-=n;if(target.hp<=0){if(target.type)killTower(target);else{target.dead=true;burst(target.x,target.y,target.side==='player'?'#86e5ce':'#ff9b83',5)}}}
function burst(x,y,color,n=6){for(let i=0;i<n;i++)particles.push({x,y,vx:(Math.random()-.5)*.32,vy:(Math.random()-.5)*.32,life:.45+Math.random()*.4,color})}
function update(dt){if(!playing)return;elapsed+=dt;energy=Math.min(10,energy+dt*(elapsed>60?.72:.55));aiWait-=dt;if(aiWait<=0){const affordable=cards.filter(c=>c.cost<=energy);if(affordable.length){const card=affordable[Math.floor(Math.random()*affordable.length)];const lane=Math.random()<.5?.26:.74;spawn(card,'enemy',lane+(Math.random()-.5)*.11,.12+Math.random()*.16);energy-=card.cost}aiWait=2.4+Math.random()*2.2}
 for(const u of units){if(u.dead)continue;u.cool-=dt;u.hit=Math.max(0,u.hit-dt);const targetU=units.filter(v=>!v.dead&&v.side!==u.side&&dist(u,v)<u.range*.95).sort((a,b)=>dist(u,a)-dist(u,b))[0];const tower=targetTower(u);const target=targetU||tower;if(target&&dist(u,target)<=u.range){if(u.cool<=0){u.cool=u.rate;u.hit=.14;if(u.kind==='splash'){units.filter(v=>!v.dead&&v.side!==u.side&&dist(v,target)<.11).forEach(v=>hurt(v,u.damage*.7));if(target.type)hurt(target,u.damage)}else hurt(target,u.damage);shots.push({x:u.x,y:u.y,tx:target.x,ty:target.y,side:u.side,life:.2});beep(u.kind==='splash'?680:420,.035)}}else if(tower){const dx=tower.x-u.x,dy=tower.y-u.y,d=Math.max(.0001,dist(u,tower));u.x+=dx/d*u.speed*dt;u.y+=dy/d*u.speed*dt;if(u.y<.52)u.y=Math.max(.54,u.y);if(u.y>.48&&u.side==='enemy')u.y=Math.min(.46,u.y)} }
 for(const t of towers){if(t.dead)continue;t.cool-=dt;const targets=units.filter(u=>!u.dead&&u.side!==t.side&&dist(u,t)<t.range).sort((a,b)=>dist(a,t)-dist(b,t));if(targets.length&&t.cool<=0){const v=targets[0];t.cool=t.rate;hurt(v,t.damage);shots.push({x:t.x,y:t.y,tx:v.x,ty:v.y,side:t.side,life:.2})}}
 for(const s of shots)s.life-=dt;shots=shots.filter(s=>s.life>0);for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt}particles=particles.filter(p=>p.life>0);units=units.filter(u=>!u.dead);
 if(elapsed>=120){const e=towers.filter(t=>t.side==='enemy').reduce((n,t)=>n+(t.dead?0:t.hp),0),p=towers.filter(t=>t.side==='player').reduce((n,t)=>n+(t.dead?0:t.hp),0);finish(playerCrowns!==enemyCrowns?playerCrowns>enemyCrowns:e<p)}if(Math.floor(elapsed)!==Math.floor(elapsed-dt))updateHud();}
function finish(win){if(ended)return;ended=true;playing=false;chosen=null;$('result-icon').textContent=win?'🏆':'🛡️';$('result-title').textContent=win?'VICTORY!':'DEFEAT';$('result-copy').textContent=win?`You claimed ${playerCrowns} ${playerCrowns===1?'crown':'crowns'} and defended your kingdom.`:`The rival claimed ${enemyCrowns} ${enemyCrowns===1?'crown':'crowns'}. Rally your troops and try again!`;$('result').classList.remove('hidden');beep(win?760:190,.3)}
function roundRect(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.stroke()}}
function draw(){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);ctx.save();ctx.scale(w,h);drawGround();for(const t of towers)drawTower(t);for(const s of shots){ctx.globalAlpha=Math.min(1,s.life*7);ctx.strokeStyle=s.side==='player'?'#bcfff0':'#ffb2a1';ctx.lineWidth=.004;ctx.beginPath();ctx.moveTo(s.x,s.y);ctx.lineTo(s.tx,s.ty);ctx.stroke();ctx.globalAlpha=1}for(const u of units)drawUnit(u);for(const p of particles){ctx.globalAlpha=Math.max(0,p.life);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,.004,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;drawPlacement();ctx.restore();}
function drawGround(){const grad=ctx.createLinearGradient(0,0,0,1);grad.addColorStop(0,'#426b5b');grad.addColorStop(.49,'#6b9b66');grad.addColorStop(.51,'#739f69');grad.addColorStop(1,'#47765c');ctx.fillStyle=grad;ctx.fillRect(0,0,1,1);
 // subtle fields and arena boundary
 ctx.fillStyle='#153d3b20';for(let i=0;i<80;i++){let x=(i*173%997)/997,y=(i*317%991)/991;ctx.beginPath();ctx.ellipse(x,y,.012,.007,(i%7)*.4,0,Math.PI*2);ctx.fill()}
 roundRect(.065,.055,.87,.89,.035,'#ffffff08','#f5e5ad55');
 // deployment tint and center divider
 ctx.fillStyle='rgba(65,205,158,.045)';ctx.fillRect(.07,.53,.86,.40);
 ctx.fillStyle='#8cc5be';ctx.fillRect(0,.477,1,.046);ctx.fillStyle='#60a9a7';ctx.fillRect(0,.492,1,.016);for(let i=0;i<11;i++){ctx.fillStyle=i%2?'#ffffff14':'#164b5060';ctx.fillRect(i*.1,.477,.05,.046)}
 // banks, bridges
 for(const x of [.26,.74]){ctx.fillStyle='#4b6453';ctx.fillRect(x-.07,.456,.14,.088);roundRect(x-.045,.457,.09,.086,.009,'#b88d5a','#ffe2a077');ctx.fillStyle='#d2b37d';for(let j=0;j<5;j++)ctx.fillRect(x-.04+j*.018,.459,.007,.08);ctx.fillStyle='#fff3';ctx.fillRect(x-.045,.458,.09,.006)}
 // river shine & arena shrubs
 ctx.strokeStyle='#c1e9d644';ctx.lineWidth=.002;for(let i=0;i<8;i++){const x=((i*137)%100)/100;ctx.beginPath();ctx.moveTo(x,.485+(i%3)*.008);ctx.lineTo(x+.035,.485+(i%3)*.008);ctx.stroke()}
 for(const [x,y] of [[.095,.34],[.905,.36],[.105,.66],[.895,.68],[.5,.28],[.5,.72]]){ctx.fillStyle='#315844';ctx.beginPath();ctx.arc(x,y,.018,0,7);ctx.fill();ctx.fillStyle='#648656';ctx.beginPath();ctx.arc(x-.006,y-.005,.011,0,7);ctx.fill()}
 // center line mark
 ctx.setLineDash([.009,.012]);ctx.strokeStyle='#fff6';ctx.lineWidth=.001;ctx.beginPath();ctx.moveTo(.075,.5);ctx.lineTo(.925,.5);ctx.stroke();ctx.setLineDash([]);
}
function drawTower(t){const x=t.x,y=t.y;const isP=t.side==='player',scale=t.type==='king'?1.24:1;const rw=.052*scale,rh=.066*scale;ctx.save();ctx.translate(x,y);ctx.fillStyle='#122c2a66';ctx.beginPath();ctx.ellipse(0,.018,rw*1.35,.025,0,0,7);ctx.fill();if(t.dead){ctx.fillStyle='#343d37';ctx.beginPath();ctx.ellipse(0,.004,rw,.025,0,0,7);ctx.fill();ctx.fillStyle='#554f43';ctx.fillRect(-rw*.7,-.018,rw*1.4,.025);ctx.restore();return}
 const base=isP?'#267c80':'#a84f4d',light=isP?'#5dd4c4':'#ff8b79',dark=isP?'#18535c':'#793a43';ctx.fillStyle=dark;ctx.fillRect(-rw,-rh*.35,rw*2,rh*.78);ctx.fillStyle=base;ctx.fillRect(-rw*.86,-rh*.49,rw*1.72,rh*.7);ctx.fillStyle=light;ctx.fillRect(-rw*.72,-rh*.48,rw*.38,rh*.66);ctx.fillStyle=dark;ctx.fillRect(-rw*1.08,-rh*.60,rw*2.16,rh*.17);
 // battlements
 for(let i=0;i<4;i++){ctx.fillStyle=light;ctx.fillRect(-rw*1.03+i*rw*.68,-rh*.72,rw*.38,rh*.22)}ctx.fillStyle='#f9dfa1';ctx.beginPath();ctx.arc(0,-rh*.4,rw*.19,0,7);ctx.fill();ctx.fillStyle='#694b3c';ctx.font=`${rw*.31}px sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(t.type==='king'?'♛':'✦',0,-rh*.4);
 const bw=rw*2.25,bh=.009;roundRect(-bw/2,-rh*.91,bw,bh,.004,'#172a31');roundRect(-bw/2,-rh*.91,bw*Math.max(0,t.hp/t.max),bh,.004,isP?'#83f0d1':'#ff9887');ctx.restore()}
function drawUnit(u){const r=u.kind==='tank'?.027:u.kind==='splash'?.021:.018;ctx.save();ctx.translate(u.x,u.y);ctx.fillStyle='#10231e66';ctx.beginPath();ctx.ellipse(0,r*1.15,r*1.2,r*.46,0,0,7);ctx.fill();ctx.fillStyle=u.side==='player'?'#164d4c':'#7b3739';ctx.beginPath();ctx.arc(0,0,r*1.12,0,7);ctx.fill();ctx.fillStyle=u.side==='player'?'#62d4bb':'#ff8b78';ctx.beginPath();ctx.arc(0,-r*.18,r*.82,0,7);ctx.fill();ctx.font=`${r*1.4}px sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(u.icon,0,-r*.02);const bw=r*2.7,bh=.006;roundRect(-bw/2,-r*1.55,bw,bh,.003,'#142128');roundRect(-bw/2,-r*1.55,bw*Math.max(0,u.hp/u.max),bh,.003,u.side==='player'?'#9df4d7':'#ffc0a5');if(u.hit>0){ctx.strokeStyle='#fff';ctx.lineWidth=.003;ctx.beginPath();ctx.arc(0,0,r*1.4,0,7);ctx.stroke()}ctx.restore()}
function drawPlacement(){if(chosen===null||!playing)return;const p=pointer;if(!p||p.y<.53)return;const card=hand[chosen];ctx.fillStyle='#6be1b021';ctx.fillRect(.07,.53,.86,.4);ctx.strokeStyle='#fff8a0';ctx.lineWidth=.002;ctx.beginPath();ctx.arc(p.x,p.y,.025,0,7);ctx.stroke();ctx.font='.026px sans-serif';ctx.textAlign='center';ctx.fillText(card.icon,p.x,p.y+.008)}
let pointer=null;canvas.addEventListener('pointermove',e=>pointer=pos(e));
function frame(now){const dt=Math.min(.04,(now-last)/1000||0);last=now;if(playing)update(dt);draw();if(playing){const remaining=Math.max(0,120-elapsed);const mm=Math.floor(remaining/60),ss=Math.floor(remaining%60);$('timer').textContent=`${mm}:${String(ss).padStart(2,'0')}`;$('phase').textContent=elapsed>60?'DOUBLE ENERGY':'BATTLE';if(hintTimer>0){hintTimer-=dt*1000;if(hintTimer<=0)say('',0)}}requestAnimationFrame(frame)}requestAnimationFrame(frame);
})();

